k"'::jsonb, '"The Supreme Court as election organizer"'::jsonb, '"Only the Governor personally"'::jsonb, '"The Zila Panchayat itself for all cities"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '0'::jsonb, '3'::jsonb, '1'::jsonb, '0'::jsonb, '2'::jsonb, '0'::jsonb, '3'::jsonb, '1'::jsonb, '0'::jsonb]::jsonb[]);

